'use strict';
const $=id=>document.getElementById(id), game=new MinesEngine.MinesGame();
let busy=false,sound=false,audioContext=null;
const money=cents=>(cents/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const multiple=value=>value.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+'×';
const board=$('board');const tiles=[];
for(let i=0;i<25;i++){const tile=document.createElement('button');tile.className='tile';tile.addEventListener('click',()=>swing(i));tiles.push(tile);board.append(tile);}
for(let i=1;i<=24;i++)$('mines').add(new Option(i,i,i===3,i===3));
function message(text,type=''){$('message').textContent=text;$('message').className='round-message '+type;}
function readBet(){const text=$('bet').value.trim();if(!/^\d+(\.\d{1,2})?$/.test(text))throw Error('베팅 금액은 소수 둘째 자리까지 입력하세요.');const [whole,fraction='']=text.split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));}
function render(){const s=game.snapshot(),active=s.status==='playing',finished=['out','cashed','cleared'].includes(s.status),k=s.hits.length;const m=active||finished?s.mines:Number($('mines').value);$('balance').innerHTML=money(s.balance)+' <small>CR</small>';$('multiplier').innerHTML=(active||finished?multiple(s.multiplier):'1.00×').replace('×','<span>×</span>');$('next').textContent=s.status==='ready'?multiple(MinesEngine.multiplier(m,1)):(s.nextMultiplier!==null?multiple(s.nextMultiplier):'—');$('hit-count').textContent=k+' HITS';$('bet').disabled=active||busy;$('mines').disabled=active||busy;$('reset').disabled=active||busy;$('lock').textContent=active?'· 잠김':'';$('round-tag').textContent=busy?'PITCH INCOMING':({ready:'READY TO PLAY',playing:'AT BAT',out:'OUT',cashed:'CASHED OUT',cleared:'PERFECT ROUND'}[s.status]);board.classList.toggle('inactive',!active);
 tiles.forEach((tile,i)=>{const hit=game.hits.has(i),hazard=finished&&game.hazards.has(i);tile.className='tile'+(hit?' hit':hazard?' out':finished?' revealed-safe':'')+(game.triggered===i?' triggered':'');tile.disabled=!active||busy||hit;tile.innerHTML=hit?'<span class="ball" aria-hidden="true">⚾</span><b>HIT</b>':hazard?'<span class="out-mark" aria-hidden="true">×</span><b>OUT</b>':finished?'<span aria-hidden="true">✓</span>':'<span class="diamond" aria-hidden="true"></span>';tile.setAttribute('aria-label',`${Math.floor(i/5)+1}행 ${i%5+1}열 ${hit?'타격 성공':hazard?'위험 코스':finished?'안전 코스':'미공개'}`);});
 $('action').disabled=busy||(active&&k===0);$('action-label').textContent=active?(busy?'타격 중':'상금 확정'):finished?'다시 타석에 들어서기':'타석에 들어서기';let amount='';if(active){amount=k?money(s.cashout)+' CR':'코스를 선택하세요'}else{try{amount=money(readBet())+' CR'}catch{amount='베팅 금액 입력'}}$('action-amount').textContent=amount;
 const p=s.status==='ready'?(25-m)/25:s.successProbability;$('probability').textContent=finished?'라운드 종료':`${k?'다음':'첫'} 타격 성공 확률 ${(100*p).toFixed(2)}%`;$('remaining').textContent='안전 코스 '+(s.status==='ready'?25-m:s.remainingSafe);
}
function tone(kind){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();void audioContext.resume();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.connect(gain);gain.connect(audioContext.destination);const t=audioContext.currentTime;oscillator.type=kind==='out'?'sawtooth':'sine';oscillator.frequency.setValueAtTime(kind==='out'?180:kind==='cash'?660:880,t);oscillator.frequency.exponentialRampToValueAtTime(kind==='out'?55:kind==='cash'?1200:440,t+.2);gain.gain.setValueAtTime(.045,t);gain.gain.exponentialRampToValueAtTime(.001,t+.25);oscillator.start(t);oscillator.stop(t+.26);}catch{}}
function flash(text,red=false){const el=$('feedback');el.textContent=text;el.className='feedback'+(red?' red':'');void el.offsetWidth;el.classList.add('show');}
function startRound(){$('feedback').classList.remove('show');if(busy)throw Error('타격 중입니다. 잠시 기다려주세요.');game.start(readBet(),Number($('mines').value));message('타격할 코스를 선택하세요');render();tone('start');return game.snapshot();}
function cashOut(){if(busy)throw Error('타격 중입니다. 잠시 기다려주세요.');const value=game.cashout();render();message(`${money(value)} CR 상금 확정 · 순이익 +${money(value-game.bet)} CR`,'win');flash('CASH OUT');tone('cash');return game.snapshot();}
async function swing(i){if(busy)throw Error('타격 중입니다. 잠시 기다려주세요.');if(game.status!=='playing'||!Number.isInteger(i)||i<0||i>=25||game.hits.has(i))throw Error('선택할 수 없는 코스입니다.');busy=true;render();message('공이 들어옵니다…');const rect=tiles[i].getBoundingClientRect(),parent=board.getBoundingClientRect();$('pitch').style.setProperty('--pitch-x',(rect.left+rect.width/2-parent.left-parent.width/2)+'px');$('pitch').style.setProperty('--pitch-y',(rect.top+rect.height/2-parent.top+parent.height*.2)+'px');$('pitch').classList.add('fly');await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?0:310));const outcome=game.reveal(i);busy=false;$('pitch').classList.remove('fly');render();if(outcome==='out'){flash('OUT',true);message(`OUT · 이번 라운드 -${money(game.bet)} CR`,'error');tone('out');}else if(outcome==='cleared'){flash('PERFECT');message(`전 코스 성공! ${money(game.lastPayout)} CR 자동 확정`,'win');tone('cash');}else{tiles[i].classList.add('new-hit');flash('HIT!');message('타격 성공! 계속 공략하거나 상금을 확정하세요','win');tone('hit');}return game.snapshot();}
$('action').addEventListener('click',()=>{try{if(game.status==='playing')cashOut();else startRound();}catch(error){message(error.message,'error');}});
$('bet').addEventListener('input',()=>{if(game.status!=='playing')render()});$('mines').addEventListener('change',()=>{if(game.status!=='playing'){if(game.status!=='ready'){game.status='ready';game.hits.clear();game.hazards.clear();game.lastPayout=0;}render();}});
$('reset').addEventListener('click',()=>{try{game.reset();$('feedback').classList.remove('show');render();message('크레딧을 1,000 CR로 초기화했습니다')}catch(error){message(error.message,'error')}});
$('help').addEventListener('click',()=>$('rules').showModal());$('close-help').addEventListener('click',()=>$('rules').close());$('rules').addEventListener('click',event=>{if(event.target===$('rules')){const rect=$('rules').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('rules').close();}});
$('sound').addEventListener('click',()=>{sound=!sound;$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');tone('hit')});
render();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const definitions=[{name:'read_game_state',description:'Read visible demo game state. Does not expose hidden danger zones.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({...game.snapshot(),busy})},{name:'start_demo_round',description:'Set a bet and danger count, then start a new demo round using virtual credits.',inputSchema:{type:'object',properties:{betCredits:{type:'number',minimum:1,maximum:1000},dangerZones:{type:'integer',minimum:1,maximum:24}},required:['betCredits','dangerZones'],additionalProperties:false},execute:input=>{if(!input||typeof input.betCredits!=='number'||!Number.isFinite(input.betCredits)||input.betCredits<1||input.betCredits>1000||Math.abs(Math.round(input.betCredits*100)-input.betCredits*100)>1e-7||!Number.isInteger(input.dangerZones)||input.dangerZones<1||input.dangerZones>24||game.status==='playing'||busy)throw Error('Invalid round settings or round already active');$('bet').value=String(input.betCredits);$('mines').value=String(input.dangerZones);return startRound();}},{name:'select_pitch_zone',description:'Select one unrevealed zone, trigger its pitch animation, then return HIT or OUT game state.',inputSchema:{type:'object',properties:{row:{type:'integer',minimum:1,maximum:5},column:{type:'integer',minimum:1,maximum:5}},required:['row','column'],additionalProperties:false},execute:async input=>{if(!input||!Number.isInteger(input.row)||input.row<1||input.row>5||!Number.isInteger(input.column)||input.column<1||input.column>5)throw Error('Invalid zone');return swing((input.row-1)*5+input.column-1);}},{name:'cash_out_demo_round',description:'Finish the current round and credit the displayed payout after at least one HIT.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>cashOut()}];for(const tool of definitions){try{Promise.resolve(context.registerTool({...tool,annotations:{readOnlyHint:false,untrustedContentHint:false,...tool.annotations}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}}

